ee:message.ee:set-payload:
%dw 2.0
output application/json
// Route keys are the positions of the routes in the scatter-gather.
var checkNames = { "0": "pricing", "1": "stock", "2": "fraud" }
var results = error.errorMessage.payload.results default {}
var failures = error.errorMessage.payload.failures default {}
---
{
	orderId: vars.vOrder.orderId,
	decision: "INCOMPLETE",
	completedChecks: results mapObject ((message, route) -> { (checkNames[route as String]): message.payload }),
	failedChecks: failures mapObject ((failure, route) -> {
		(checkNames[route as String]): {
			// Only the error type: the description can carry internal details (the requester's URL, for one),
			// so it is logged above and never sent to the caller.
			errorType: failure.errorType.namespace ++ ":" ++ failure.errorType.identifier
		}
	})
}
